import math, json, os

targets = {"physical":1.5,"meta":2.0,"being":3.2}
ws = [
    {"w": 0.12688, "label": "interpolated_zero_crossing_physical (Test C)"},
    {"w": 0.30,    "label": "meta-level cascade marker"},
    {"w": 1.00,    "label": "pure Beta reference"}
]

def classify(b):
    best_label, best_delta = None, float("inf")
    for k,v in targets.items():
        d = abs(b - v)
        if d < best_delta:
            best_label, best_delta = k, d
    tag = best_label
    if b > max(targets.values()) * 1.15:
        tag = "beyond"
    return {"label": tag, "nearest": best_label, "delta": best_delta}

out = []
for item in ws:
    w = item["w"]
    base = 5.0 / (5.0 ** w)
    out.append({
        "w": w,
        "label": item["label"],
        "base": base,
        "class": classify(base)
    })

os.makedirs("storage/shared/atlas/analysis/cascade_meta", exist_ok=True)
txt = "Base Inference (relative to c*_meta=5.0)\n"
for r in out:
    txt += f"w={r['w']:.5f} | base={r['base']:.6f} | class={r['class']['label']} (nearest={r['class']['nearest']}, Δ={r['class']['delta']:.3f}) | note={r['label']}\n"
with open("storage/shared/atlas/analysis/cascade_meta/alignment_quick_report.txt","w",encoding="utf-8") as f:
    f.write(txt)

print(json.dumps({"report": "storage/shared/atlas/analysis/cascade_meta/alignment_quick_report.txt", "results": out}, ensure_ascii=False))
